{"file_path":"cell-WCbPK8/src/lexer.js","content":"// A hand-written scanner for the small language described in the task.
//
// scanSource(source) returns an array of tokens:
//   { line, col, kind, body }
// where kind is one of 'ident', 'keyword', 'number', 'punct', 'rawstring',
// 'string', and body is the source text for every kind except 'string' and
// 'rawstring', for which it is the *decoded* value (the caller is
// responsible for turning that into a JSON string when printing).
//
// On error it throws an Error with `isLexError = true`, `pos = {line,col}`
// and `message` set to the bare reason text (no `error:` prefix, no
// position prefix -- the caller adds those).

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTS2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCTS1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

function isAlpha(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}
function isIdentChar(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}
function isDec(c) {
  return c !== undefined && c >= '0' && c <= '9'
}
function isHex(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBin(c) {
  return c === '0' || c === '1'
}
function isOct(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

class LexError extends Error {
  constructor(pos, message) {
    super(message)
    this.isLexError = true
    this.pos = pos
  }
}

export function scanSource(source) {
  const chars = Array.from(source)
  const len = chars.length
  let i = 0
  let line = 1
  let col = 1

  function peekAt(o = 0) {
    return chars[i + o]
  }
  function currentPos() {
    return { line, col }
  }
  function advance() {
    const c = chars[i]
    i++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }
  function fail(pos, message) {
    throw new LexError(pos, message)
  }

  function collectRun(test) {
    let run = ''
    let lastWasDigit = false
    for (;;) {
      const c = peekAt(0)
      if (c !== undefined && test(c)) {
        run += advance()
        lastWasDigit = true
        continue
      }
      if (c === '_' && lastWasDigit && test(peekAt(1))) {
        run += advance()
        lastWasDigit = false
        continue
      }
      break
    }
    return run
  }

  function scanIdent() {
    const pos = currentPos()
    let text = advance()
    while (isIdentChar(peekAt(0))) {
      text += advance()
    }
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { line: pos.line, col: pos.col, kind, body: text }
  }

  function scanNumber() {
    const pos = currentPos()
    let text = ''
    let invalidPrefix = false
    const c0 = peekAt(0)
    const c1 = peekAt(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
      text += advance()
      text += advance()
      const digits = collectRun(isHex)
      text += digits
      if (digits.length === 0) invalidPrefix = true
    } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
      text += advance()
      text += advance()
      const digits = collectRun(isBin)
      text += digits
      if (digits.length === 0) invalidPrefix = true
    } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
      text += advance()
      text += advance()
      const digits = collectRun(isOct)
      text += digits
      if (digits.length === 0) invalidPrefix = true
    } else {
      text += collectRun(isDec)
      if (peekAt(0) === '.' && isDec(peekAt(1))) {
        text += advance()
        text += collectRun(isDec)
      }
      if (peekAt(0) === 'e' || peekAt(0) === 'E') {
        const p1 = peekAt(1)
        if (isDec(p1)) {
          text += advance()
          text += collectRun(isDec)
        } else if ((p1 === '+' || p1 === '-') && isDec(peekAt(2))) {
          text += advance()
          text += advance()
          text += collectRun(isDec)
        }
      }
    }

    let invalid = invalidPrefix
    const trailing = peekAt(0)
    if (trailing !== undefined && /[A-Za-z0-9_]/.test(trailing)) {
      text += advance()
      invalid = true
    }
    if (invalid) {
      fail(pos, 'invalid number ' + text)
    }
    return { line: pos.line, col: pos.col, kind: 'number', body: text }
  }

  function scanString() {
    const pos = currentPos()
    advance() // opening quote
    let decoded = ''
    for (;;) {
      if (i >= len) fail(pos, 'unterminated string')
      const cpos = currentPos()
      const c = peekAt(0)
      if (c === '"') {
        advance()
        break
      }
      if (c === '\n') {
        fail(cpos, 'newline in string')
      }
      if (c === '\\') {
        const bpos = cpos
        advance() // backslash
        if (i >= len) fail(pos, 'unterminated string')
        const e = peekAt(0)
        if (e === 'n') {
          advance()
          decoded += '\n'
        } else if (e === 't') {
          advance()
          decoded += '\t'
        } else if (e === 'r') {
          advance()
          decoded += '\r'
        } else if (e === '\\') {
          advance()
          decoded += '\\'
        } else if (e === '"') {
          advance()
          decoded += '"'
        } else if (e === '0') {
          advance()
          decoded += '\0'
        } else if (e === 'x') {
          advance()
          const h1 = peekAt(0)
          const h2 = peekAt(1)
          if (isHex(h1) && isHex(h2)) {
            advance()
            advance()
            decoded += String.fromCharCode(parseInt(h1 + h2, 16))
          } else {
            fail(bpos, 'invalid escape \\x')
          }
        } else if (e === 'u') {
          advance()
          if (peekAt(0) !== '{') fail(bpos, 'invalid escape \\u')
          advance()
          let hex = ''
          while (isHex(peekAt(0))) {
            hex += advance()
          }
          if (hex.length === 0) fail(bpos, 'invalid escape \\u')
          if (peekAt(0) !== '}') fail(bpos, 'invalid escape \\u')
          advance()
          const code = parseInt(hex, 16)
          if (code > 0x10ffff) fail(bpos, 'invalid escape \\u')
          decoded += String.fromCodePoint(code)
        } else {
          fail(bpos, 'invalid escape \\' + e)
        }
      } else {
        decoded += advance()
      }
    }
    return { line: pos.line, col: pos.col, kind: 'string', body: decoded }
  }

  function scanRawString() {
    const pos = currentPos()
    advance() // 'r'
    const quotePos = currentPos()
    advance() // '"'
    let raw = ''
    for (;;) {
      if (i >= len) fail(quotePos, 'unterminated string')
      const c = peekAt(0)
      if (c === '"') {
        advance()
        break
      }
      raw += advance()
    }
    return { line: pos.line, col: pos.col, kind: 'rawstring', body: raw }
  }

  const tokens = []

  while (i < len) {
    const c = peekAt(0)

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }

    if (c === '/' && peekAt(1) === '/') {
      advance()
      advance()
      while (i < len && peekAt(0) !== '\n') {
        advance()
      }
      continue
    }

    if (c === '/' && peekAt(1) === '*') {
      const openPos = currentPos()
      advance()
      advance()
      let depth = 1
      while (depth > 0) {
        if (i >= len) fail(openPos, 'unterminated block comment')
        if (peekAt(0) === '/' && peekAt(1) === '*') {
          advance()
          advance()
          depth++
          continue
        }
        if (peekAt(0) === '*' && peekAt(1) === '/') {
          advance()
          advance()
          depth--
          continue
        }
        advance()
      }
      continue
    }

    if (c === 'r' && peekAt(1) === '"') {
      tokens.push(scanRawString())
      continue
    }

    if (c === '"') {
      tokens.push(scanString())
      continue
    }

    if (isAlpha(c) || c === '_') {
      tokens.push(scanIdent())
      continue
    }

    if (isDec(c)) {
      tokens.push(scanNumber())
      continue
    }

    const two = c + (peekAt(1) === undefined ? '' : peekAt(1))
    if (PUNCTS2.includes(two)) {
      const pos = currentPos()
      advance()
      advance()
      tokens.push({ line: pos.line, col: pos.col, kind: 'punct', body: two })
      continue
    }
    if (PUNCTS1.includes(c)) {
      const pos = currentPos()
      advance()
      tokens.push({ line: pos.line, col: pos.col, kind: 'punct', body: c })
      continue
    }

    const pos = currentPos()
    fail(pos, 'unexpected character ' + c)
  }

  return tokens
}
"}

