/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scanSource } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scanSource(source)
  } catch (e) {
    if (e && e.isLexError) {
      process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.body) : t.body
      out += `${t.line}:${t.col} ${t.kind} ${body}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    let out = ''
    for (const k of KIND_ORDER) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
}

main()
"}

